/**
 * SuiSui live-run-progress reporter (feature 011).
 *
 * Generated by SuiSui into <workspace>/.app/ and appended to Playwright's
 * --reporter chain. It runs inside the WORKSPACE's Playwright process, so it is
 * plain CommonJS with no dependencies and no build step.
 *
 * It emits one sentinel-prefixed NDJSON line per event on stdout. SuiSui's main
 * process strips those lines out of the stream before the run log reaches the
 * user, so nothing here is ever shown raw.
 *
 * NON-NEGOTIABLE: this file must never be able to break a test run. Every
 * callback body is wrapped, and any failure degrades to "no live progress"
 * rather than a failed run.
 *
 * Do not edit — it is overwritten on every run.
 */

const SENTINEL = '@@SUISUI_PROGRESS@@'

/** Count of `test.step` entries seen per test, which is the step's ordinal. */
const stepCounters = new Map()
/** Maps a Playwright step object to the ordinal we assigned it at stepBegin. */
const stepIndexes = new WeakMap()

function emit(payload) {
  try {
    process.stdout.write(`${SENTINEL}${JSON.stringify(payload)}\n`)
  } catch {
    // A failed write must not surface to the test run.
  }
}

/**
 * Feature file path relative to the features directory, derived from the
 * generated spec path. Mirrors SuiSui's `extractFeatureRelativePath`.
 */
function featureRelativePath(file) {
  if (typeof file !== 'string') return ''
  const normalized = file.replace(/\\/g, '/')
  const generated = normalized.match(/(?:^|\/)\.features-gen\/(.+?)\.spec\.[jt]s$/)
  if (generated && generated[1]) return generated[1]
  const plain = normalized.match(/([^/].*?)\.spec\.[jt]s$/)
  return plain && plain[1] ? plain[1] : normalized
}

/** A stable id for one test, independent of retries. */
function testKey(test) {
  if (test && typeof test.id === 'string' && test.id.length > 0) return test.id
  const loc = (test && test.location) || {}
  return `${loc.file || ''}:${loc.line || 0}:${loc.column || 0}`
}

class SuiSuiProgressReporter {
  onBegin(_config, suite) {
    try {
      let totalTests
      try {
        totalTests = suite && typeof suite.allTests === 'function' ? suite.allTests().length : undefined
      } catch {
        totalTests = undefined
      }
      emit(totalTests === undefined ? { type: 'runStart' } : { type: 'runStart', totalTests })
    } catch {
      /* never throw out of a reporter callback */
    }
  }

  onTestBegin(test, result) {
    try {
      const testId = testKey(test)
      // A retry restarts the step numbering for this test.
      stepCounters.set(testId, 0)
      emit({
        type: 'testStart',
        testId,
        relativePath: featureRelativePath(test && test.location && test.location.file),
        title: (test && test.title) || '',
        attempt: (result && result.retry) || 0,
        at: Date.now(),
      })
    } catch {
      /* never throw */
    }
  }

  onStepBegin(test, _result, step) {
    try {
      // Only authored Gherkin steps: playwright-bdd wraps each one in
      // test.step(). Hooks, fixtures and expect() calls use other categories.
      if (!step || step.category !== 'test.step') return

      const testId = testKey(test)
      const index = stepCounters.get(testId) || 0
      stepCounters.set(testId, index + 1)
      stepIndexes.set(step, index)

      emit({
        type: 'stepStart',
        testId,
        index,
        title: step.title || '',
        at: Date.now(),
      })
    } catch {
      /* never throw */
    }
  }

  onStepEnd(test, _result, step) {
    try {
      if (!step || step.category !== 'test.step') return

      const index = stepIndexes.get(step)
      if (index === undefined) return

      emit({
        type: 'stepEnd',
        testId: testKey(test),
        index,
        // Carried so SuiSui can verify the ordinal it matched and drop the
        // update rather than mark the wrong step.
        title: step.title || '',
        status: step.error ? 'failed' : 'passed',
        durationMs: typeof step.duration === 'number' ? step.duration : 0,
        ...(step.error && step.error.message ? { error: String(step.error.message) } : {}),
        at: Date.now(),
      })
    } catch {
      /* never throw */
    }
  }

  onTestEnd(test, result) {
    try {
      const testId = testKey(test)
      stepCounters.delete(testId)

      const raw = (result && result.status) || 'failed'
      const status =
        raw === 'passed' ? 'passed'
        : raw === 'skipped' ? 'skipped'
        : raw === 'interrupted' ? 'interrupted'
        : 'failed'

      emit({
        type: 'testEnd',
        testId,
        status,
        durationMs: (result && result.duration) || 0,
        at: Date.now(),
      })
    } catch {
      /* never throw */
    }
  }

  onEnd() {
    try {
      emit({ type: 'runEnd', at: Date.now() })
    } catch {
      /* never throw */
    }
  }

  /** Keep Playwright's own stdout/stderr handling untouched. */
  printsToStdio() {
    return false
  }
}

module.exports = SuiSuiProgressReporter
